package br.com.sussmartcare.queue.infrastructure.messaging;
import br.com.sussmartcare.queue.application.QueueApplicationService; import com.fasterxml.jackson.databind.*; import java.util.*; import org.springframework.kafka.annotation.KafkaListener; import org.springframework.stereotype.Component; import org.springframework.transaction.annotation.Transactional;
@Component public class QueueLifecycleConsumer {private final ObjectMapper mapper;private final ProcessedEventRepository processed;private final VisitFacilityLinkRepository links;private final PendingQueuePriorityRepository pending;private final QueueApplicationService app;public QueueLifecycleConsumer(ObjectMapper m,ProcessedEventRepository p,VisitFacilityLinkRepository l,PendingQueuePriorityRepository q,QueueApplicationService a){mapper=m;processed=p;links=l;pending=q;app=a;}
 private EventPayload begin(String raw)throws Exception{var e=mapper.readTree(raw);UUID id=UUID.fromString(e.path("eventId").asText());if(processed.existsById(id))return null;return new EventPayload(id,e.path("data"));}
 @KafkaListener(topics="pre-visit-created",groupId="queue-visit-map")@Transactional public void visit(String raw)throws Exception{var e=begin(raw);if(e==null)return;var d=e.data();UUID visit=UUID.fromString(d.path("visitId").asText());UUID facility=UUID.fromString(d.path("facilityId").asText());links.save(new VisitFacilityLink(visit,facility));pending.findById(visit).ifPresent(p->{app.enterIfAbsent(visit,facility,p.getPriority());pending.delete(p);});processed.save(new ProcessedEvent(e.eventId(),"queue-visit-map"));}
 @KafkaListener(topics="clinical-priority-confirmed",groupId="queue-clinical-priority")@Transactional public void priority(String raw)throws Exception{var e=begin(raw);if(e==null)return;var d=e.data();UUID visit=UUID.fromString(d.path("visitId").asText());String priority=d.path("priority").asText();var link=links.findById(visit);if(link.isPresent())app.enterIfAbsent(visit,link.get().getFacilityId(),priority);else pending.save(new PendingQueuePriority(visit,priority));processed.save(new ProcessedEvent(e.eventId(),"queue-clinical-priority"));}
 private record EventPayload(UUID eventId,JsonNode data){}
}
